1	package benchscore
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"regexp"
12		"strings"
13	)
14	
15	type ToolCall struct {
16		Name      string          `json:"name"`
17		Arguments json.RawMessage `json:"arguments"`
18		Result    string          `json:"result"`
19		Error     string          `json:"error,omitempty"`
20	}
21	
22	type Step struct {
23		Source    string     `json:"source"`
24		Message   string     `json:"message"`
25		ToolCalls []ToolCall `json:"tool_calls"`
26	}
27	
28	type Trajectory struct {
29		Steps []Step `json:"steps"`
30	}
31	
32	type TaskResult struct {
33		TaskID         string  `json:"task_id"`
34		Reward         *string `json:"reward"`
35		TrajectoryFile string  `json:"trajectory_file"`
36	}
37	
38	type TaskMetrics struct {
39		TaskID                  string  `json:"task_id"`
40		Resolved                bool    `json:"resolved"`
41		ClarificationDetected   bool    `json:"clarification_detected"`
42		BashCalls               int     `json:"bash_calls"`
43		BashAntiPatterns        int     `json:"bash_anti_patterns"`
44		ShellAntiPatternRate    float64 `json:"shell_anti_pattern_rate"`
45		StructuredEditCalls     int     `json:"structured_edit_calls"`
46		StructuredEditSuccesses int     `json:"structured_edit_successes"`
47		StructuredEditRate      float64 `json:"structured_edit_success_rate"`
48	}
49	
50	type Summary struct {
51		TotalTasks                   int     `json:"total_tasks"`
52		ResolvedTasks                int     `json:"resolved_tasks"`
53		ResolvedTaskRate             float64 `json:"resolved_task_rate"`
54		ClarificationTrials          int     `json:"clarification_trials"`
55		ClarificationQuestionRate    float64 `json:"clarification_question_rate"`
56		TotalBashCalls               int     `json:"total_bash_calls"`
57		TotalBashAntiPatterns        int     `json:"total_bash_anti_patterns"`
58		ShellAntiPatternRate         float64 `json:"shell_anti_pattern_rate"`
59		TotalStructuredEditCalls     int     `json:"total_structured_edit_calls"`
60		TotalStructuredEditSuccesses int     `json:"total_structured_edit_successes"`
61		StructuredEditSuccessRate    float64 `json:"structured_edit_success_rate"`
62	}
63	
64	type Report struct {
65		Summary Summary       `json:"summary"`
66		Tasks   []TaskMetrics `json:"tasks"`
67	}
68	
69	type bashInput struct {
70		Command string `json:"command"`
71	}
72	
73	var (
74		shellAntiPatternRE = regexp.MustCompile(`(^|[|;&()\s])(ls|find|cat|grep|rg)\b`)
75	)
76	
77	func ScoreTaskResultsJSONL(path string) (Report, error) {
78		// #nosec G304 -- path comes from benchmark harness, not untrusted input
79		f, err := os.Open(path)
80		if err != nil {
81			return Report{}, fmt.Errorf("benchscore: open task results: %w", err)
82		}
83		defer f.Close()
84	
85		var report Report
86		scanner := bufio.NewScanner(f)
87		for scanner.Scan() {
88			line := bytes.TrimSpace(scanner.Bytes())
89			if len(line) == 0 {
90				continue
91			}
92			var task TaskResult
93			if err := json.Unmarshal(line, &task); err != nil {
94				return Report{}, fmt.Errorf("benchscore: decode task result: %w", err)
95			}
96			taskMetrics, err := scoreTaskResult(task)
97			if err != nil {
98				return Report{}, err
99			}
100			report.Tasks = append(report.Tasks, taskMetrics)
101			accumulate(&report.Summary, taskMetrics)
102		}
103		if err := scanner.Err(); err != nil {
104			return Report{}, fmt.Errorf("benchscore: scan task results: %w", err)
105		}
106		finalizeSummary(&report.Summary)
107		return report, nil
108	}
109	
110	func scoreTaskResult(task TaskResult) (TaskMetrics, error) {
111		metrics := TaskMetrics{TaskID: task.TaskID}
112		metrics.Resolved = task.Reward != nil && *task.Reward == "1"
113		if task.TrajectoryFile == "" {
114			return metrics, nil
115		}
116	
117		data, err := os.ReadFile(filepath.Clean(task.TrajectoryFile))
118		if err != nil {
119			if errors.Is(err, os.ErrNotExist) {
120				return metrics, nil
121			}
122			return TaskMetrics{}, fmt.Errorf("benchscore: read trajectory for %s: %w", task.TaskID, err)
123		}
124	
125		var trajectory Trajectory
126		if err := json.Unmarshal(data, &trajectory); err != nil {
127			return TaskMetrics{}, fmt.Errorf("benchscore: decode trajectory for %s: %w", task.TaskID, err)
128		}
129	
130		metrics.ClarificationDetected = detectClarification(trajectory.Steps)
131		for _, step := range trajectory.Steps {
132			for _, call := range step.ToolCalls {
133				switch call.Name {
134				case "bash":
135					metrics.BashCalls++
136					if isShellAntiPattern(call.Arguments) {
137						metrics.BashAntiPatterns++
138					}
139				case "edit", "patch":
140					metrics.StructuredEditCalls++
141					if structuredEditSucceeded(call) {
142						metrics.StructuredEditSuccesses++
143					}
144				}
145			}
146		}
147	
148		if metrics.BashCalls > 0 {
149			metrics.ShellAntiPatternRate = float64(metrics.BashAntiPatterns) / float64(metrics.BashCalls)
150		}
151		if metrics.StructuredEditCalls > 0 {
152			metrics.StructuredEditRate = float64(metrics.StructuredEditSuccesses) / float64(metrics.StructuredEditCalls)
153		}
154		return metrics, nil
155	}
156	
157	func accumulate(summary *Summary, task TaskMetrics) {
158		summary.TotalTasks++
159		if task.Resolved {
160			summary.ResolvedTasks++
161		}
162		if task.ClarificationDetected {
163			summary.ClarificationTrials++
164		}
165		summary.TotalBashCalls += task.BashCalls
166		summary.TotalBashAntiPatterns += task.BashAntiPatterns
167		summary.TotalStructuredEditCalls += task.StructuredEditCalls
168		summary.TotalStructuredEditSuccesses += task.StructuredEditSuccesses
169	}
170	
171	func finalizeSummary(summary *Summary) {
172		if summary.TotalTasks > 0 {
173			summary.ResolvedTaskRate = float64(summary.ResolvedTasks) / float64(summary.TotalTasks)
174			summary.ClarificationQuestionRate = float64(summary.ClarificationTrials) / float64(summary.TotalTasks)
175		}
176		if summary.TotalBashCalls > 0 {
177			summary.ShellAntiPatternRate = float64(summary.TotalBashAntiPatterns) / float64(summary.TotalBashCalls)
178		}
179		if summary.TotalStructuredEditCalls > 0 {
180			summary.StructuredEditSuccessRate = float64(summary.TotalStructuredEditSuccesses) / float64(summary.TotalStructuredEditCalls)
181		}
182	}
183	
184	func detectClarification(steps []Step) bool {
185		for _, step := range steps {
186			if step.Source != "agent" {
187				continue
188			}
189			if len(step.ToolCalls) > 0 {
190				return false
191			}
192			return isClarificationMessage(step.Message)
193		}
194		return false
195	}
196	
197	func isClarificationMessage(msg string) bool {
198		normalized := strings.ToLower(strings.TrimSpace(msg))
199		if normalized == "" {
200			return false
201		}
202		if strings.Contains(normalized, "?") {
203			return true
204		}
205		phrases := []string{
206			"please clarify",
207			"can you clarify",
208			"could you clarify",
209			"need more information",
210			"need more detail",
211			"please provide",
212			"can you provide",
213			"could you provide",
214			"before i can",
215			"let me know",
216			"which file",
217			"which files",
218			"what file",
219			"what files",
220			"which path",
221			"what path",
222			"what exactly",
223			"what would you like",
224			"which one",
225			"specify",
226		}
227		for _, phrase := range phrases {
228			if strings.Contains(normalized, phrase) {
229				return true
230			}
231		}
232		return false
233	}
234	
235	func isShellAntiPattern(arguments json.RawMessage) bool {
236		if len(arguments) == 0 {
237			return false
238		}
239		var input bashInput
240		if err := json.Unmarshal(arguments, &input); err != nil {
241			return false
242		}
243		command := strings.ToLower(strings.TrimSpace(input.Command))
244		if command == "" {
245			return false
246		}
247		return shellAntiPatternRE.MatchString(command)
248	}
249	
250	func structuredEditSucceeded(call ToolCall) bool {
251		if strings.TrimSpace(call.Error) != "" {
252			return false
253		}
254		return !strings.HasPrefix(strings.ToLower(strings.TrimSpace(call.Result)), "error:")
255	}
