package main

import (
	"bytes"
	"os"
	"os/exec"
	"strings"
	"testing"
)

func TestBenchscoreCommandName(t *testing.T) {
	got := benchscoreCommandName()
	want := "fiz-benchscore"
	if got != want {
		t.Errorf("benchscoreCommandName() = %q, want %q", got, want)
	}
}

func TestUsageContainsFizBenchscore(t *testing.T) {
	exe, err := os.Executable()
	if err != nil {
		t.Skip("cannot determine test binary path:", err)
	}
	// Run the test binary as a subprocess in a mode that invokes main.
	// We use the standard go test trick: if TEST_MAIN_INVOKE is set, call main().
	cmd := exec.Command(exe, "-test.run=TestHelperMain")
	cmd.Env = append(os.Environ(), "GO_TEST_HELPER_MAIN=1")
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	_ = cmd.Run()
	output := stderr.String()
	if !strings.Contains(output, "fiz-benchscore") {
		t.Errorf("usage output does not contain %q; got: %q", "fiz-benchscore", output)
	}
}

// TestHelperMain is invoked as a subprocess to test main() exit behaviour.
func TestHelperMain(t *testing.T) {
	if os.Getenv("GO_TEST_HELPER_MAIN") != "1" {
		t.Skip("not running as subprocess helper")
	}
	// Simulate missing -tasks-jsonl: override os.Args so flag.Parse sees no flags.
	os.Args = []string{"fiz-benchscore"}
	main()
}

package main

